  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C31"],
      "claim": "Gallopamil showed 96.3% oral bioavailability in humans, well above the 20% threshold, supporting high F."
    },
    {
      "card_ids": ["C08"],
      "claim": "Vernakalant had absolute oral bioavailability of 71 ± 21% in fasted healthy volunteers, supporting high F."
    },
    {
      "card_ids": ["C10"],
      "claim": "Verapamil had absolute oral bioavailability of 18–20% in patients, which is borderline around the threshold; other verapamil records are mixed, so this does not affirmatively establish low F."
    }
  ],
  "confidence": "moderate",
  "contradictory_card_ids": ["C10"],
  "decision_summary": "Most transferred evidence, including absolute oral bioavailability values of 96.3% and 71±21%, supports F≥20%; the only borderline evidence (verapamil ~18–22%) is mixed around the threshold and does not affirmatively support low F. Therefore predict high with moderate confidence.",
  "evidence_gaps": [
    "Verapamil evidence is mixed around the 20% threshold, with some values below 20% and some above, so it does not provide a clear molecule-level direction.",
    "Some records are qualitative or unspecified bioavailability type, lowering precision but not reversing direction."
  ],
  "new_evidence_assessment": [],
  "prediction_basis_card_ids": ["C31", "C08"],
  "revision_action": "initial",
